"""Emprendimiento y Empleabilidad EPJA Media N1 y N2, módulo 1: emprendimientos y emprendedores (OAD-01), necesidades y problemas del entorno (OAD-02), soluciones creativas con criterios sociales, éticos y ambientales (OAD-03) y modelo de negocio (OAD-04). Casos ficticios rotulados; todo en papel."""
from __future__ import annotations

from hc_common import make_build

MATERIALS = "Papel, lápiz y goma. Todos los casos, cifras y fichas son de ejemplo (personas y negocios ficticios); no se usa dinero real, calculadora ni internet. Todo se resuelve con lo escrito en la ficha."
build = make_build(MATERIALS)

O1 = "EPJA-EMEM-NM1y2-OAD-01"
O2 = "EPJA-EMEM-NM1y2-OAD-02"
O3 = "EPJA-EMEM-NM1y2-OAD-03"
O4 = "EPJA-EMEM-NM1y2-OAD-04"
PRIOR = ["He visto negocios, ferias y oficios en mi barrio o mi comunidad.", "Alguna vez he resuelto un problema con lo que tenía a mano."]


def K(oa, n, F, use, explain, vocab, worked, mistakes, T, ctx, sc, op, rf, ex_, prior=None):
    stmt, example, crit, ev, err, fb = op
    build(oa, n, F, use=use, prior=prior or PRIOR, explain=explain, vocab=vocab, worked=worked, mistakes=mistakes, T=T, ctx=ctx, sc=sc,
          op=(stmt, example, crit, ev, err, fb), reinforce=rf, extend=ex_)


