   ("=", "{F} ¿Cuál es el puntaje total del problema A? Suma 3, 2 y 3.", "3+2+3", "Se suman los tres criterios puntuados en la ficha.", " puntos"),
   ("=", "{F} ¿Cuál es el puntaje total del problema B? Suma 2, 2 y 2.", "2+2+2", "Se suman los tres criterios del problema B.", " puntos"),
